namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Semester { get; set; } = "";
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [StringLength(500)]
    public string Notes { get; set; } = "";
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Exploration of abstract structures, quantities, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Understanding the fundamental laws governing the natural world." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
            new() { Id = 5, Name = "Biology", Code = "BIO", Description = "The science of life and living organisms." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Semester = "Fall 2026", IsFeatured = true, Instructor = new() { Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. Her research focuses on CS education and making programming accessible to all students.", Email = "s.chen@university.edu" } },
            new() { Id = 2, DepartmentId = 1, Code = "CS201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Semester = "Fall 2026", IsFeatured = true, Instructor = new() { Name = "Dr. James Park", Title = "Professor", Bio = "Dr. Park is a leading researcher in algorithm optimization with publications in top-tier venues. He brings real-world examples from industry into the classroom.", Email = "j.park@university.edu" } },
            new() { Id = 3, DepartmentId = 1, Code = "CS350", Title = "Database Systems", Description = "Relational database design, SQL, transaction processing, and an introduction to NoSQL databases. Includes a semester-long project building a complete application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Semester = "Fall 2026", Instructor = new() { Name = "Dr. Maria Rodriguez", Title = "Assistant Professor", Bio = "Dr. Rodriguez spent 8 years in industry at major tech companies before joining academia. She specializes in distributed database systems.", Email = "m.rodriguez@university.edu" } },
            new() { Id = 4, DepartmentId = 2, Code = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Semester = "Fall 2026", IsFeatured = true, Instructor = new() { Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim has authored three calculus textbooks and received the university's Distinguished Teaching Award twice.", Email = "r.kim@university.edu" } },
            new() { Id = 5, DepartmentId = 2, Code = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors. Essential for CS, physics, and engineering students.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Semester = "Fall 2026", Instructor = new() { Name = "Dr. Emily Watson", Title = "Associate Professor", Bio = "Dr. Watson's research bridges abstract algebra and computational mathematics. She is passionate about visualizing mathematical concepts.", Email = "e.watson@university.edu" } },
            new() { Id = 6, DepartmentId = 3, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, waves, and thermodynamics. Includes weekly lab sessions. Calculus-based.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", Semester = "Fall 2026", IsFeatured = true, Instructor = new() { Name = "Dr. Alan Foster", Title = "Professor", Bio = "Dr. Foster is an experimental physicist whose research in quantum optics has been featured in Nature and Science.", Email = "a.foster@university.edu" } },
            new() { Id = 7, DepartmentId = 3, Code = "PHYS301", Title = "Quantum Mechanics", Description = "Wave functions, Schrödinger equation, quantum states, measurement theory, and applications to atomic and molecular systems.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Semester = "Fall 2026", Instructor = new() { Name = "Dr. Lisa Chang", Title = "Associate Professor", Bio = "Dr. Chang is a theoretical physicist specializing in quantum information theory. She has mentored over 20 graduate students.", Email = "l.chang@university.edu" } },
            new() { Id = 8, DepartmentId = 4, Code = "ENG101", Title = "Composition & Rhetoric", Description = "Develop clear, effective writing skills. Covers essay structure, argumentation, research methods, and academic citation.", Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", Semester = "Fall 2026", Instructor = new() { Name = "Prof. David Miller", Title = "Senior Lecturer", Bio = "Prof. Miller is a published author and writing coach with 20 years of experience helping students find their voice.", Email = "d.miller@university.edu" } },
            new() { Id = 9, DepartmentId = 4, Code = "ENG250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present. Examines major movements, themes, and cultural contexts.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Semester = "Fall 2026", Instructor = new() { Name = "Dr. Angela Brooks", Title = "Professor", Bio = "Dr. Brooks is a specialist in 20th-century American fiction and has published extensively on the Harlem Renaissance.", Email = "a.brooks@university.edu" } },
            new() { Id = 10, DepartmentId = 5, Code = "BIO101", Title = "Introduction to Biology", Description = "Cell biology, genetics, evolution, and ecology. Includes lab work with microscopy and molecular biology techniques.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Tue Lab 9:00–11:50 AM", Semester = "Fall 2026", IsFeatured = true, Instructor = new() { Name = "Dr. Patricia Nguyen", Title = "Associate Professor", Bio = "Dr. Nguyen is a molecular biologist whose research on gene expression has been funded by the NIH for over a decade.", Email = "p.nguyen@university.edu" } },
            new() { Id = 11, DepartmentId = 5, Code = "BIO310", Title = "Microbiology", Description = "Study of microorganisms including bacteria, viruses, fungi, and protists. Covers pathogenesis, immunology, and applied microbiology.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Semester = "Fall 2026", Instructor = new() { Name = "Dr. Thomas Wright", Title = "Professor", Bio = "Dr. Wright has spent his career studying antibiotic resistance and has advised public health organizations worldwide.", Email = "t.wright@university.edu" } },
            new() { Id = 12, DepartmentId = 1, Code = "CS410", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, deep learning fundamentals, and practical applications using Python and TensorFlow.", Credits = 3, Schedule = "Mon/Wed 4:00–5:20 PM", Semester = "Fall 2026", IsFeatured = true, Instructor = new() { Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. Her research focuses on CS education and making programming accessible to all students.", Email = "s.chen@university.edu" } }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";
}

